def is_magic(grid):
    s = 111
    # rows
    for i in range(6):
        if sum(grid[i*6:(i+1)*6]) != s:
            return False
    # cols
    for j in range(6):
        if sum(grid[k*6 + j] for k in range(6)) != s:
            return False
    # diags
    if sum(grid[i*6 + i] for i in range(6)) != s:
        return False
    if sum(grid[i*6 + (5-i)] for i in range(6)) != s:
        return False
    return True

